from pydantic import BaseModel

app = FastAPI()

todos = []
_next_id = 1


class TodoIn(BaseModel):
    title: str


@app.get('/todos')
def list_todos():
    return todos


@app.post('/todos', status_code=201)
def create_todo(item: TodoIn):
    global _next_id
    todo = {'id': _next_id, 'title': item.title}
    _next_id += 1
    todos.append(todo)
    return todo


@app.delete('/todos/{todo_id}')
def delete_todo(todo_id: int):
    # BUG: always reports success even if no todo had that id.
    global todos
    todos = [t for t in todos if t['id'] != todo_id]
    return Response(status_code=204)


if __name__ == '__main__':
    import uvicorn
    uvicorn.run(app, port=8010)
